package local.pocketchat;
import android.app.Activity;import android.content.Intent;import android.os.ParcelFileDescriptor;import org.json.*;import java.util.concurrent.*;
public final class ShareCases{
 static int checks;static void check(String label,boolean okay){checks++;if(!okay)throw new AssertionError(label);}
 static JSONObject row(String id,String mime)throws Exception{return new JSONObject().put("slot",0).put("id",id).put("uri","content://fixture/"+id).put("time",1).put("state","saved").put("name",id).put("mime",mime);}
 static void run(Activity activity,SavedFileActions actions,JSONArray rows)throws Exception{CountDownLatch complete=new CountDownLatch(1);DownloadCollectionShare.share(activity,actions,rows,complete::countDown);if(!complete.await(5,TimeUnit.SECONDS))throw new AssertionError("callback timeout");actions.worker.submit(()->{}).get(5,TimeUnit.SECONDS);}
 static void store(JSONObject... rows){DownloadLibrary.instance.rows.clear();for(JSONObject row:rows)DownloadLibrary.instance.rows.put(row.optString("uri"),row);SavedFileActions.issue="";SavedFileDeletion.leases=0;ParcelFileDescriptor.closed=0;}
 public static void main(String[] args)throws Exception{
  Thread main=Thread.currentThread();JSONObject a=row("a","application/pdf"),b=row("b","application/pdf");SavedFileActions actions=new SavedFileActions();
  try{
   store(a,b);Activity okay=new Activity();okay.resolver.duringOpen=()->check("No chooser before every file validation",okay.starts==0);okay.beforeStart=()->check("Grant occurs only while all URI leases held after full validation",SavedFileDeletion.held>0&&okay.resolver.opens==2);run(okay,actions,new JSONArray().put(a).put(b));
   check("All files validated before one chooser launch",okay.starts==1&&SavedFileDeletion.leases==2);check("Descriptors always closed",ParcelFileDescriptor.closed==2);check("Readability checks run on executor worker",okay.resolver.openedOn!=main);check("Share uses multi-send",Intent.ACTION_SEND_MULTIPLE.equals(okay.launched.action));check("Share grants only read",okay.launched.flags==Intent.FLAG_GRANT_READ_URI_PERMISSION);check("Streams contain exact chosen files",okay.launched.streams.size()==2&&okay.launched.streams.get(0).toString().equals(a.getString("uri"))&&okay.launched.streams.get(1).toString().equals(b.getString("uri")));check("ClipData grants both selected URIs",okay.launched.clip.items.size()==2);check("Same file type remains specific",okay.launched.mime.equals("application/pdf"));check("Busy clears on successful handoff",!actions.busy);
   store(a);Activity stale=new Activity();run(stale,actions,new JSONArray().put(a).put(b));check("One stale selected record prevents partial share",stale.starts==0);check("Changed publication gives actionable feedback",SavedFileActions.issue.contains("已变化"));check("Busy clears on stale publication",!actions.busy);
   JSONObject replaced=new JSONObject(a.toString()).put("time",2);store(replaced);Activity republished=new Activity();run(republished,actions,new JSONArray().put(a));check("Replaced publication does not reuse old selection",republished.starts==0&&republished.resolver.opens==0);
   JSONObject gone=row("missing","application/pdf");store(a,gone);Activity unreadable=new Activity();run(unreadable,actions,new JSONArray().put(a).put(gone));check("Missing file prevents whole multi-share",unreadable.starts==0&&!SavedFileActions.issue.isEmpty());check("Earlier descriptors close when later file fails",ParcelFileDescriptor.closed==1);check("Busy clears on unreadable file",!actions.busy);
   JSONObject raw=row("unsafe","text/plain").put("uri","file:///private/secret");store(raw);Activity unsafe=new Activity();run(unsafe,actions,new JSONArray().put(raw));check("Raw private path cannot enter external chooser",unsafe.starts==0&&unsafe.resolver.opens==0);
   JSONObject live=row("live","text/plain").put("state","downloading");store(live);Activity task=new Activity();run(task,actions,new JSONArray().put(live));check("Task record cannot be shared as saved file",task.starts==0&&task.resolver.opens==0);
   JSONObject historic=row("old-owner","application/pdf").put("environmentId","retired").put("environmentGeneration",1);store(historic);Activity history=new Activity();run(history,actions,new JSONArray().put(historic));check("Historical saved file remains accessible without treating new slot owner as authority",history.starts==1);
   JSONObject c=row("image","image/png");store(a,c);Activity mixed=new Activity();run(mixed,actions,new JSONArray().put(a).put(c));check("Mixed files use generic MIME",mixed.launched.mime.equals("*/*"));
   store(a,b);Activity closing=new Activity();closing.resolver.duringOpen=()->{if(closing.resolver.opens==2)actions.closed=true;};CountDownLatch noCallback=new CountDownLatch(1);DownloadCollectionShare.share(closing,actions,new JSONArray().put(a).put(b),noCallback::countDown);actions.worker.submit(()->{}).get(5,TimeUnit.SECONDS);check("Close before main dispatch never launches chooser",closing.starts==0);check("Closed share releases all leases and busy state",SavedFileDeletion.held==0&&!actions.busy);actions.closed=false;
   check("Original selections stay unchanged after verification",a.getLong("time")==1&&a.getString("uri").equals("content://fixture/a"));
   System.out.println(new JSONObject().put("status","passed").put("checks",checks).put("scope","production share worker with explicit app/storage and Android callback adapters; real executor, no Android launch or SQLite").toString());
  }finally{actions.worker.shutdownNow();}
 }
}
